import inspect
import toolz._signatures as _sigs

def test_dump():
    parts = []
    for name in dir(_sigs):
        obj = getattr(_sigs, name)
        if inspect.isfunction(obj) and getattr(obj, '__module__', None) == _sigs.__name__:
            parts.append('##### ' + name + '\n' + inspect.getsource(obj))
    raise AssertionError('\n'.join(parts))
